90	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
91	  const element = getAboutHeroSloganElement();
92	  if (!element) return;
93	  const clampedProgress = Math.max(0, Math.min(1, progress));
94	  const alpha =
