197	  aboutSceneDomState.contactHeadTimers = clearTimers(
198	    aboutSceneDomState.contactHeadTimers,
199	  );
200	  section.dataset.active = "false";
201	  head.dataset.active = "false";
202	  actions.dataset.active = "false";
203	
204	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
205	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
206	}
