29	import { DEFAULT_MAIN_SCENE_STATE } from "../../main/theatre/MainSceneState.js";
30	
31	export class AboutSceneRig {
32	  compose(state: AboutSceneState): SceneFromState {
33	    return {
34	      camera: {
35	        position: { ...state.camera.position },
36	        fov: state.camera.fov,
37	      },
38	      cameraTarget: {
39	        position: { ...state.camera.target },
40	      },
41	      [aboutBackgroundId]: state.background,
42	      [earthId]: state.earth,
43	      [rocketId]: state.rocket,
44	      [jetEngineId]: {
45	        position: { ...state.jetEngine.position },
46	        rotation: { ...state.jetEngine.rotation },
47	        scale: { ...state.jetEngine.scale },
48	        visible: state.jetEngine.visible,
49	      },
50	      [astronautId]: state.astronaut,
51	      [terrianId]: state.terrian,
52	    } as unknown as SceneFromState;
53	  }
54	
55	  apply(engine: Engine, state: AboutSceneState): void {
56	    engine.setState(this.compose(state));
57	    const camera = engine.getCamera();
58	    camera.lookAt(engine.getCameraTarget().position);
59	    this._applyLight(engine, state.light);
60	    this._applyRocket(engine, state.rocket);
61	    this._applyJetEngine(engine, state.jetEngine);
62	  }
63	
64	  read(engine: Engine): AboutSceneState {
65	    const camera = engine.getCamera();
66	    const target = engine.getCameraTarget();
67	    return {
68	      camera: {
69	        position: {
70	          x: this._toFinite(camera.position.x, 0),
71	          y: this._toFinite(camera.position.y, 0),
72	          z: this._toFinite(camera.position.z, 18),
73	        },
74	        target: {
75	          x: this._toFinite(target.position.x, 0),
76	          y: this._toFinite(target.position.y, 0),
77	          z: this._toFinite(target.position.z, 0),
78	        },
79	        fov: this._toFinite(camera.fov, 64),
80	      },
81	      light: this._readLight(engine),
82	      background: this._readBackground(engine),
83	      earth: this._readTransform(engine, earthId),
84	      rocket: this._readRocket(engine),
85	      jetEngine: this._readJetEngine(engine),
86	      astronaut: this._readTransform(engine, astronautId),
87	      terrian: this._readTransform(engine, terrianId),
88	    };
89	  }
90	
91	  private _readRocket(engine: Engine): MainRocketState {
92	    const transform = this._readTransform(engine, rocketId);
93	    const defaults = DEFAULT_MAIN_SCENE_STATE.rocket;
94	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
95	    return {
96	      ...transform,
97	      flame: rocket?.getFlameState() ?? defaults.flame,
98	    };
99	  }
100	
101	  private _applyRocket(engine: Engine, state: MainRocketState): void {
102	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
103	    if (!rocket) return;
104	    rocket.setFlameState(state.flame);
