492	  private _writeMatchStartKeyframe(
493	    currentObject: AboutTheatreObject,
494	    currentSequence: TheatreSequencePort,
495	    previousValues: AboutTheatreValue,
496	  ): void {
497	    const previousPosition = currentSequence.position;
498	    const scrub = TheatreStudioService.createScrub<
499	      AboutTheatreValue,
500	      AboutTheatreProps
501	    >();
502	    currentSequence.pause();
503	    currentSequence.position = 0;
