511	  private _resolveSheetEndPosition(
512	    sheetId: AboutTheatreSheetId,
513	    sequence: TheatreSequencePort,
514	  ): number {
515	    const saveFile = TheatreStudioService.createContentOfSaveFile(
516	      ABOUT_THEATRE_PROJECT_ID,
517	    );
518	    const sheetsById = this._readRecord(saveFile?.sheetsById);
519	    const sheetState = this._readRecord(sheetsById?.[sheetId]);
520	    const sequenceState = this._readRecord(sheetState?.sequence);
521	    const tracksByObject = this._readRecord(sequenceState?.tracksByObject);
522	    const objectTracks = this._readRecord(tracksByObject?.[ABOUT_THEATRE_OBJECT_ID]);
523	    const trackData = this._readRecord(objectTracks?.trackData);
524	    if (!trackData) {
525	      return sequence.length > 0 ? sequence.length : 0;
526	    }
527	
528	    let maxPosition = Number.NEGATIVE_INFINITY;
529	    Object.values(trackData).forEach((trackState) => {
530	      const trackRecord = this._readRecord(trackState);
531	      const keyframes = trackRecord?.keyframes;
532	      if (!Array.isArray(keyframes)) return;
533	      keyframes.forEach((keyframe) => {
534	        const keyframeRecord = this._readRecord(keyframe);
535	        const position = keyframeRecord?.position;
536	        if (typeof position !== "number" || !Number.isFinite(position)) return;
537	        maxPosition = Math.max(maxPosition, position);
538	      });
539	    });
540	
541	    if (!Number.isFinite(maxPosition)) {
542	      return sequence.length > 0 ? sequence.length : 0;
543	    }
544	    return maxPosition;
545	  }
