747	  private _normalizeSheetState(
748	    sheetState: unknown,
749	    sheetId: AboutTheatreSheetId,
750	  ): Record<string, unknown> | null {
751	    const sheetRecord = this._readRecord(sheetState);
752	    if (!sheetRecord) return null;
753	    if (this._sheetHasMeaningfulKeyframes(sheetRecord, sheetId)) {
754	      return sheetRecord;
755	    }
756	    return null;
757	  }
758	
759	  private _sheetHasMeaningfulKeyframes(
760	    sheetState: Record<string, unknown>,
761	    sheetId: AboutTheatreSheetId,
762	  ): boolean {
763	    const sequenceState = this._readRecord(sheetState.sequence);
764	    if (!sequenceState) return false;
765	    const tracksByObject = this._readRecord(sequenceState.tracksByObject);
766	    if (!tracksByObject) return false;
767	    const objectTracks = this._readRecord(tracksByObject[ABOUT_THEATRE_OBJECT_ID]);
768	    if (!objectTracks) return false;
769	    const trackData = this._readRecord(objectTracks.trackData);
770	    if (!trackData) return false;
771	    const sequence = this._sequenceBySheetId.get(sheetId);
772	    if (!sequence) return false;
773	    return Object.values(trackData).some((trackState) =>
774	      this._trackHasMeaningfulKeyframes(trackState, sequence),
775	    );
776	  }
777	
778	  private _trackHasMeaningfulKeyframes(
779	    trackState: unknown,
780	    sequence: TheatreSequencePort,
781	  ): boolean {
782	    const trackRecord = this._readRecord(trackState);
783	    if (!trackRecord) return false;
784	    const keyframes = trackRecord.keyframes;
785	    if (!Array.isArray(keyframes) || keyframes.length === 0) {
786	      return false;
787	    }
788	    const positions = keyframes
789	      .map((keyframe) => {
790	        const keyframeRecord = this._readRecord(keyframe);
791	        const position = keyframeRecord?.position;
792	        return typeof position === "number" && Number.isFinite(position)
793	          ? position
794	          : null;
795	      })
796	      .filter((position): position is number => position != null);
797	    return positions.length > 0;
798	  }
