258	  resolveSceneProgressState(
259	    sceneKey: AboutSceneSectionKey,
260	    progress: number,
261	  ): AboutSceneProgressState | null {
262	    const resolvedSteps = this._resolveSceneSteps(sceneKey)
263	      .map((step) => this._resolveStep(step))
264	      .filter((step): step is AboutResolvedTheatrePlaybackStep => step != null);
265	    if (resolvedSteps.length === 0) {
266	      if (DEBUG_SCENE_KEYS.includes(sceneKey)) {
267	        Logger.warn(CLASS, "resolveSceneProgressState", "No theatre steps resolved.", {
268	          sceneKey,
269	          progress,
270	        });
271	      }
272	      return null;
273	    }
274	    const clampedProgress = this._clampPosition(progress, 1);
275	    for (const step of resolvedSteps) {
276	      if (!this._isProgressWithinRange(clampedProgress, step.progressRange)) {
277	        continue;
278	      }
279	      const nextState = {
280	        sheetId: step.sheetId,
281	        localProgress: this._resolveLocalProgress(
282	          clampedProgress,
283	          step.progressRange,
284	        ),
285	      };
286	      if (
287	        DEBUG_SCENE_KEYS.includes(sceneKey) &&
288	        shouldLogDebugBucket(
289	          debugResolveLogKeyByScene,
290	          sceneKey,
291	          "resolve",
292	          progress,
293	          nextState.sheetId,
294	        )
295	      ) {
296	        Logger.info(
297	          CLASS,
298	          "resolveSceneProgressState",
299	          `Resolved theatre progress for ${sceneKey}.`,
300	          {
301	            sceneKey,
302	            progress,
303	            clampedProgress,
304	            resolvedStep: step,
305	            nextState,
306	          },
307	        );
308	      }
309	      return nextState;
310	    }
311	    if (
312	      DEBUG_SCENE_KEYS.includes(sceneKey) &&
313	      shouldLogDebugBucket(
314	        debugResolveLogKeyByScene,
315	        sceneKey,
316	        "resolve-miss",
317	        progress,
318	      )
319	    ) {
320	      Logger.warn(
321	        CLASS,
322	        "resolveSceneProgressState",
323	        "Resolved steps exist but none matched current progress.",
324	        {
325	          sceneKey,
326	          progress,
327	          clampedProgress,
328	          resolvedSteps,
329	        },
330	      );
331	    }
332	    return null;
333	  }
