451	  private _resolvePlaybackRange(
452	    sheetId: AboutTheatreSheetId,
453	    length: number,
454	  ): AboutTheatrePlaybackRange {
455	    const configuredRange = this._playbackRangeBySheetId.get(sheetId) ?? null;
456	    if (configuredRange) {
457	      return {
458	        start: this._clampPosition(configuredRange.start, length),
459	        end: this._clampPosition(configuredRange.end, length),
460	      };
461	    }
462	    return {
463	      start: 0,
464	      end: Number.isFinite(length) && length > 0 ? length : 0,
465	    };
466	  }
