554	  private _readSheetLengthFromState(sheetId: AboutTheatreSheetId): number {
555	    const sheetsById = readAboutRecord(this._stateSource.sheetsById);
556	    if (!sheetsById) return 0;
557	    const sheetState = readAboutRecord(sheetsById[sheetId]);
558	    if (!sheetState) return 0;
559	    const sequence = readAboutRecord(sheetState.sequence);
560	    if (!sequence) return 0;
561	    const length = sequence.length;
562	    if (typeof length !== "number" || !Number.isFinite(length) || length <= 0) {
563	      return 0;
564	    }
565	    return length;
566	  }
