568	  private _clampPosition(position: number, length: number): number {
569	    if (!Number.isFinite(length) || length <= 0) return 0;
570	    if (!Number.isFinite(position)) return 0;
571	    if (position <= 0) return 0;
572	    if (position >= length) return length;
573	    return position;
574	  }
