576	  private _syncSheetState(
577	    engine: Engine,
578	    sheetId: AboutTheatreSheetId,
579	    position: number,
580	  ): void {
581	    this._rig.apply(engine, mergeAboutTheatreValue(this.readState(sheetId, position)));
582	  }
